  })));

  const kept = toKeep.slice().sort((a,b) => new Date(a.start_iso) - new Date(b.start_iso));
  let cursor = new Date(fromIso);
  const segments = [];
  for (const l of kept) {
    const s = new Date(l.start_iso), e = new Date(l.end_iso);
