    const today = new Date(); today.setHours(0,0,0,0);
    const dOnly = new Date(d); dOnly.setHours(0,0,0,0);
    const diffDays = Math.round((dOnly - today) / 86400000);
    let label;
    if (diffDays === 0) label = 'Today';
    else if (diffDays === 1) label = 'Tomorrow';
    else if (diffDays === -1) label = 'Yesterday';
    else label = d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
    out.push({ id: 'divider-' + key, type: 'divider', label });
    lastKey = key;
  }
  out.push(item);
}
return out;

